"""Regenerate resample-pillow.ts (Pillow reference outputs for src/utils/resample.ts).

    uv run --with pillow python -I src/test/fixtures/resample-pillow.gen.py > src/test/fixtures/resample-pillow.ts
    pnpm format

`pattern` must stay byte-identical to `resampleTestPattern` in the generated
TS. Boxes are kept float32-exact (Pillow passes them to C as `float`).
"""

import PIL
from PIL import Image


def pattern(width, height, alpha):
    buf = bytearray()
    for y in range(height):
        for x in range(width):
            for c in range(3):
                buf.append((x * 37 + y * 91 + c * 53 + ((x * y) % 7) * 29) % 256)
            if not alpha:
                buf.append(255)
            elif (x * 13 + y * 7) % 5 == 0:
                buf.append(0)
            else:
                buf.append((x * 29 + y * 17) % 256)
    return Image.frombytes("RGBA", (width, height), bytes(buf))


# name, (width, height), alpha, target, box (x0, y0, x1, y1) or None, reducing_gap
CASES = [
    ("fullBox", (48, 40), False, (7, 6), None, None),
    ("fractionalBox", (48, 40), False, (9, 8), (5.5, 3.25, 36.0, 30.25), None),
    ("verticalPassFirst", (12, 10), False, (17, 3), None, None),
    ("passOrderBoundary", (20, 20), False, (18, 16), None, None),
    ("rowOffset", (100, 100), False, (40, 10), (10.0, 50.0, 90.0, 70.0), None),
    ("alpha", (48, 40), True, (7, 6), None, None),
    ("alphaFractionalBox", (48, 40), True, (9, 8), (5.5, 3.25, 36.0, 30.25), None),
    ("reducingGap5x5", (300, 200), False, (19, 13), None, 3.0),
    ("reducingGap3x1Box", (300, 20), False, (25, 15), (0.5, 0.0, 300.0, 20.0), 3.0),
    ("reducingGap2x2Alpha", (120, 90), True, (20, 15), None, 3.0),
    # reduce() edge blocks the factor doesn't divide, and a safe box away from the origin.
    ("reducingGapPartialBlocks", (301, 203), True, (17, 11), (37.25, 11.5, 290.75, 199.0), 3.0),
    # The favicon path: a 1000x587 letterbox into 16px, at the Resizer's gap
    # and at the icon generators' THUMBNAIL_REDUCING_GAP.
    ("reducingGapFavicon", (1000, 587), False, (16, 9), None, 3.0),
    ("thumbnailReducingGapFavicon", (1000, 587), True, (16, 9), None, 2.0),
    ("reducingGapVerticalPassFirst", (12, 300), False, (11, 4), None, 3.0),
]


def ts_number(value):
    return str(int(value)) if float(value).is_integer() else repr(value)


lines = [
    "/**",
    " * Pillow reference outputs for `resampleRgba` (src/utils/resample.ts).",
    " *",
    f" * Generated by resample-pillow.gen.py with Pillow {PIL.__version__} — edit that",
    " * script, not this file. Each case is",
    " * `Image.frombytes('RGBA', size, pattern).resize(target, LANCZOS, box, reducing_gap)`.",
    " */",
    "",
    "/** RGBA test pattern; must stay byte-identical to `pattern` in the generator. */",
    "export const resampleTestPattern = (width: number, height: number, alpha: boolean): Uint8ClampedArray => {",
    "  const data = new Uint8ClampedArray(width * height * 4)",
    "  for (let y = 0; y < height; y++) {",
    "    for (let x = 0; x < width; x++) {",
    "      const i = (y * width + x) * 4",
    "      for (let c = 0; c < 3; c++) {",
    "        data[i + c] = (x * 37 + y * 91 + c * 53 + ((x * y) % 7) * 29) % 256",
    "      }",
    "      data[i + 3] = !alpha ? 255 : (x * 13 + y * 7) % 5 === 0 ? 0 : (x * 29 + y * 17) % 256",
    "    }",
    "  }",
    "  return data",
    "}",
    "",
    "export const PILLOW_LANCZOS_CASES = [",
]
for name, (width, height), alpha, target, box, gap in CASES:
    out = pattern(width, height, alpha).resize(target, Image.Resampling.LANCZOS, box, gap)
    x0, y0, x1, y1 = box or (0, 0, width, height)
    lines += [
        "  {",
        f"    alpha: {'true' if alpha else 'false'},",
        f"    box: {{ height: {ts_number(y1 - y0)}, width: {ts_number(x1 - x0)}, x: {ts_number(x0)}, y: {ts_number(y0)} }},",
        f"    expected: [{', '.join(str(v) for v in out.tobytes())}],",
        f"    name: '{name}',",
        f"    reducingGap: {ts_number(gap) if gap else 'undefined'},",
        f"    source: {{ height: {height}, width: {width} }},",
        f"    target: {{ height: {target[1]}, width: {target[0]} }},",
        "  },",
    ]
lines.append("]")
print("\n".join(lines))
